    inp = entry['input']
    out = entry['output']
    h = len(inp)
    w = len(inp[0])

    unchanged = []
    changed = []
    changed_colors = {}

    for r in range(h):
        for c in range(w):
            if inp[r][c] != out[r][c]:
                changed.append((r, c))
                changed_colors.setdefault(inp[r][c], []).append(out[r][c])
