    print(f"\nDemo {i}: {len(unchanged)} unchanged cells, {len(changed)} changed cells")

    # Show changes
    if changed:
        change_summary = sorted(changed)[:10]
        print(f"  First 10 changes: {change_summary}...")

    if changed_colors:
        for src, dst_list in sorted(changed_colors.items()):
            print(f"  Color {src} contributes to: {set(dst_list)}")

    # Show where unchanged cells are for prominent colors
